WITH sales_agg AS ( SELECT cs_warehouse_sk, SUM(cs_net_profit) AS total_net_profit, SUM(cs_quantity) AS total_sales_qty, MAX(cs_net_paid) AS max_net_paid FROM catalog_sales WHERE cs_promo_sk IS NOT NULL GROUP BY cs_warehouse_sk ), inv_agg AS ( SELECT inv_warehouse_sk, SUM(inv_quantity_on_hand) AS total_inventory_qty, COUNT(*) AS sku_count FROM inventory GROUP BY inv_warehouse_sk ) SELECT w.w_warehouse_name, w.w_city, COALESCE(s.total_net_profit, 0) AS total_net_profit, COALESCE(s.total_sales_qty, 0) AS total_sales_qty, COALESCE(i.total_inventory_qty, 0) AS total_inventory_qty, COALESCE(i.sku_count, 0) AS sku_count, COALESCE(s.max_net_paid, 0) AS max_net_paid, CASE WHEN COALESCE(s.total_net_profit, 0) > 0 THEN 'Profit' WHEN COALESCE(s.total_net_profit, 0) < 0 THEN 'Loss' ELSE 'Break-even' END AS profit_status, DENSE_RANK() OVER (ORDER BY COALESCE(s.max_net_paid, 0) DESC) AS max_paid_rank FROM warehouse w LEFT JOIN sales_agg s ON w.w_warehouse_sk = s.cs_warehouse_sk LEFT JOIN inv_agg i ON w.w_warehouse_sk = i.inv_warehouse_sk ORDER BY max_paid_rank, w.w_warehouse_name LIMIT 25
